var i=`contract-testing`;var s=86;var n={en:[{id:`T086-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Contract Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Mutation testing changes code in small controlled ways and checks whether the test suite detects those changes.`},{id:`B`,text:`Technical debt describes future engineering cost caused by design and implementation shortcuts or changing needs.`},{id:`C`,text:`Property-based testing checks general invariants over many generated inputs rather than only hand-picked examples.`},{id:`D`,text:`Contract testing verifies assumptions between service providers and consumers, such as request shapes, response semantics and event schemas.`}]},{id:`T086-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Contract Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Use consumer-driven contracts or shared schemas with executable verification.`},{id:`B`,text:`Record debt with business impact, risk, affected modules, approximate remediation cost and triggers.`},{id:`C`,text:`Choose unit tests for isolated rules, integration tests for storage and service boundaries, and E2E tests for critical user journeys.`},{id:`D`,text:`Define properties such as round-trip correctness, preservation of totals or order independence where valid.`}]},{id:`T086-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`},{id:`B`,text:`Given a paid reservation inside the free-cancellation window, when the guest cancels, then refund eligibility is recorded and inventory becomes available according to policy.`},{id:`C`,text:`Contract tests flag an API release that removes a status or changes a 409 conflict response.`},{id:`D`,text:`For a discount engine, first assert behavior at thresholds, empty carts and incompatible coupons; then implement rules and refactor duplicated conditions.`}]},{id:`T086-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Contract Testing`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Excessive mocks can test a fictional system, while broad E2E tests are slow and flaky.`},{id:`B`,text:`Matching JSON shapes alone misses semantics, authorization and performance.`},{id:`C`,text:`Static analysis has false positives and blind spots for runtime state and business logic.`},{id:`D`,text:`Not every imperfect design is debt worth repaying.`}]},{id:`T086-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It helps detect integration breaks without running every service together.`}]}]},{id:`T086-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Provider tests alone prove every consumer uses the contract correctly.`}]}]},{id:`T086-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Avoid overly strict snapshots that reject harmless additive fields; complement contracts with integration and E2E tests.`}]}]},{id:`T086-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Contract Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Property-based testing is equivalent to generating arbitrary random inputs with no invariants.`},{id:`B`,text:`Contract testing verifies assumptions between service providers and consumers, such as request shapes, response semantics and event schemas.`},{id:`C`,text:`Use consumer-driven contracts or shared schemas with executable verification.`},{id:`D`,text:`A contract test can replace all system-level integration tests in a deployment.`}]},{id:`T086-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Contract Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A generator that never explores boundary values is sufficient for every property.`},{id:`B`,text:`Avoid overly strict snapshots that reject harmless additive fields; complement contracts with integration and E2E tests.`},{id:`C`,text:`Contract tests flag an API release that removes a status or changes a 409 conflict response.`},{id:`D`,text:`Provider tests alone prove every consumer uses the contract correctly.`}]},{id:`T086-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to rank five debt items by risk, frequency and refactoring cost, then propose incremental repayment with test and rollback checkpoints.`},{id:`B`,text:`Ask an agent to propose CI static checks for a modular backend, including forbidden dependencies, unsafe input flows and targeted suppressions.`},{id:`C`,text:`Ask an agent for one meaningful test at each layer for reservation confirmation. Explain which failures each catches and which remain uncovered.`},{id:`D`,text:`Ask an agent to create a consumer contract for booking cancellation, including a 409 error and optional new fields, then verify two server versions.`}]},{id:`T086-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What incompatible behavioral change could pass schema validation?`}]}]},{id:`T086-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Contract Testing`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T086-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0},{t:` — propose three checks for `},{t:`Contract Testing`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T086-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T086-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Contract Testing`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A booking frontend expects reservation status values and error codes.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T086-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Контрактне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Мутаційне тестування вносить невеликі контрольовані зміни до коду й перевіряє, чи виявляють їх тести.`},{id:`B`,text:`Технічний борг — майбутні інженерні витрати через скорочені рішення або зміну потреб.`},{id:`C`,text:`Property-based testing перевіряє загальні інваріанти на багатьох згенерованих входах, а не лише вручну обраних прикладах.`},{id:`D`,text:`Контрактне тестування перевіряє домовленості між провайдером і споживачем: форми запитів, семантику відповідей і схеми подій.`}]},{id:`T086-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Контрактне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Використовуйте consumer-driven контракти або спільні схеми з виконуваною перевіркою.`},{id:`B`,text:`Фіксуйте борг із бізнесовим впливом, ризиком, модулями, приблизною ціною виправлення й тригерами.`},{id:`C`,text:`Використовуйте unit-тести для окремих правил, інтеграційні — для БД та сервісних меж, E2E — для ключових шляхів користувача.`},{id:`D`,text:`Визначайте властивості на кшталт round-trip, збереження суми або незалежності від порядку, якщо вона справді потрібна.`}]},{id:`T086-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`},{id:`B`,text:`За умови оплаченого бронювання в період безкоштовного скасування, коли гість скасовує його, право на повернення коштів фіксується, а номер стає доступним за правилами.`},{id:`C`,text:`Контрактні тести виявлять реліз API, що видалив статус або змінив 409 conflict.`},{id:`D`,text:`Для рушія знижок спершу перевірте пороги, порожній кошик і несумісні купони; потім реалізуйте правила й відрефакторіть повтори умов.`}]},{id:`T086-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Контрактне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Надмірні mocks тестують вигадану систему, а широкі E2E повільні й нестабільні.`},{id:`B`,text:`Збіг JSON-схеми не гарантує семантику, авторизацію чи швидкість.`},{id:`C`,text:`Статичний аналіз має false positives і не бачить усі runtime-стани та бізнес-правила.`},{id:`D`,text:`Не кожен недосконалий дизайн варто виправляти.`}]},{id:`T086-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Воно знаходить несумісність без запуску всіх сервісів одночасно.`}]}]},{id:`T086-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Лише тести провайдера доводять, що всі споживачі правильно використовують контракт.`}]}]},{id:`T086-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не використовуйте надто суворі snapshots, які блокують додавання необов’язкових полів; доповнюйте інтеграційними й E2E тестами.`}]}]},{id:`T086-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Контрактне тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Property-based testing — це просто випадкові дані без визначених інваріантів.`},{id:`B`,text:`Контрактне тестування перевіряє домовленості між провайдером і споживачем: форми запитів, семантику відповідей і схеми подій.`},{id:`C`,text:`Використовуйте consumer-driven контракти або спільні схеми з виконуваною перевіркою.`},{id:`D`,text:`Контрактний тест може замінити всі інтеграційні тести системи.`}]},{id:`T086-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Контрактне тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Генератора без граничних значень достатньо для будь-якої властивості.`},{id:`B`,text:`Не використовуйте надто суворі snapshots, які блокують додавання необов’язкових полів; доповнюйте інтеграційними й E2E тестами.`},{id:`C`,text:`Контрактні тести виявлять реліз API, що видалив статус або змінив 409 conflict.`},{id:`D`,text:`Лише тести провайдера доводять, що всі споживачі правильно використовують контракт.`}]},{id:`T086-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента оцінити п’ять боргів за ризиком, частотою й ціною змін та запропонувати поетапне погашення з тестами й точками відкату.`},{id:`B`,text:`Попросіть агента запропонувати статичні перевірки CI для модульного бекенду: заборонені залежності, небезпечні потоки даних і точкові suppressions.`},{id:`C`,text:`Попросіть агента зробити по одному змістовному тесту кожного рівня для підтвердження бронювання. Поясніть, які збої вони ловлять, а які ні.`},{id:`D`,text:`Попросіть агента створити споживчий контракт скасування бронювання, включно з 409 та новими необов’язковими полями, і перевірити дві версії сервера.`}]},{id:`T086-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Яка несумісна зміна поведінки може пройти перевірку схеми?`}]}]},{id:`T086-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Контрактне тестування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T086-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Контрактне тестування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T086-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T086-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Контрактне тестування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Фронтенд бронювань очікує конкретні статуси й коди помилок.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:86,questions:n};export{r as default,n as questions,i as slug,s as topicId};